{
  "units": [
    {
      "quote": "The term “applicant” is used hereinafter for the individual whose citizenship and identity is being adjudicated, including for form DS-2060.",
      "scope_quotes": [],
      "kind": "definition",
      "meaning": "Hereinafter, 'applicant' refers to the person whose citizenship and identity are subject to adjudication, which includes adjudications involving form DS-2060."
    },
    {
      "quote": "For purposes of this chapter, minor applicants are defined as un-emancipated applicants under the age of 18.",
      "scope_quotes": [],
      "kind": "definition",
      "meaning": "Within this chapter, 'minor applicants' means un-emancipated individuals under 18 years of age."
    },
    {
      "quote": "A material discrepancy is any name change that is not defined as immaterial in 8 FAM 403.1-5.",
      "scope_quotes": [],
      "kind": "definition",
      "meaning": "Any name change that 8 FAM 403.1-5 does not define as immaterial constitutes a material discrepancy."
    },
    {
      "quote": "The applicant must explain any material discrepancies between the name on the application and the name recorded in the evidence of U.S. citizenship/non-citizen U.S. nationality and the evidence of identity (see 22 CFR 51.25).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "The applicant is required to provide an explanation for any material discrepancies existing between the name stated on the passport application and the name shown in the evidence of identity and evidence of U.S. citizenship or non-citizen U.S. nationality."
    },
    {
      "quote": "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section (see an exception for married names in 8 FAM 403.1-4(C)).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Unless the married names exception in 8 FAM 403.1-4(C) applies, material discrepancies across the application name, citizenship/nationality evidence, or identity evidence must be documented by submitting at least one acceptable document listed in this section."
    },
    {
      "quote": "Court orders or decrees:\n\n(a) Name change orders; or\n\n(b) Divorce decrees;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Court orders or decrees—specifically name change orders or divorce decrees—are acceptable documentation of a material name change."
    },
    {
      "quote": "Certificates of naturalization;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Certificates of naturalization are recognized as an acceptable means to document a material name change."
    },
    {
      "quote": "Marriage certificates;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Marriage certificates are recognized as an acceptable means to document a material name change."
    },
    {
      "quote": "Documentation demonstrating change of name by operation of state law; or",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Documentation demonstrating a name change occurred by operation of state law is recognized as an acceptable means to document a material name change."
    },
    {
      "quote": "Documentation of customary usage.",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Documentation showing customary usage is recognized as an acceptable means to document a material name change."
    },
    {
      "quote": "Evidence of material name changes must be reviewed for evidence of counterfeiting or alteration (see 8 FAM 201.1)",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Adjudicators must examine evidence submitted for material name changes to check for signs of alteration or counterfeiting."
    },
    {
      "quote": "The applicant may not continue to use a previous name after a material name change unless the name change documentation specifically permits the applicant to continue using that name (see 8 FAM 403.1-6 regarding “known as” names).",
      "scope_quotes": [],
      "kind": "prohibition",
      "meaning": "An applicant is prohibited from continuing to use a previous name following a material name change, unless the name change documentation expressly allows them to keep using that previous name."
    },
    {
      "quote": "under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:",
      "scope_quotes": [
        "The applicant's name is an integral part of her/his identity. Consequently,"
      ],
      "kind": "condition",
      "meaning": "Evidence of identity may be required pursuant to Department guidance to determine the name that best identifies the applicant, recognizing the name as an integral component of identity."
    },
    {
      "quote": "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name.",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "If an applicant applying on form DS-11 underwent a material name change more than one year before applying but did not update their ID to the new name, the application must be suspended to request an acceptable ID showing the new name."
    },
    {
      "quote": "If there is insufficient time to request that the applicant submit acceptable ID prior to urgent or emergency travel, a limited-validity passport may be issued in the requested name;",
      "scope_quotes": [
        "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change,"
      ],
      "kind": "permission",
      "meaning": "When an applicant with an outdated ID from a name change more than one year before a DS-11 application faces urgent or emergency travel that leaves insufficient time to request and obtain acceptable ID, adjudicators may issue a limited-validity passport in the requested name."
    },
    {
      "quote": "The applicant generally will need the name change documentation to change the name on her/his ID.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "An applicant typically requires their name change documentation in order to update the name on their ID."
    },
    {
      "quote": "You must fully notate the name change documentation prior to returning the documentation, including that the documentation was \"seen and returned,\" to the applicant with the information request letter (IRL);",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Before returning name change documentation to the applicant alongside an Information Request Letter (IRL), adjudicators must fully notate the documentation, including recording that it was 'seen and returned.'"
    },
    {
      "quote": "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name.",
      "scope_quotes": [],
      "kind": "exemption",
      "meaning": "Applicants whose material name change took place within one year before applying on form DS-11 are exempt from submitting ID reflecting their new name."
    },
    {
      "quote": "However, if the ID has not yet been changed, they must submit their name change documentation.",
      "scope_quotes": [
        "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name."
      ],
      "kind": "requirement",
      "meaning": "If an applicant whose material name change occurred within one year of applying on form DS-11 has not yet changed their ID, they are required to submit their name change documentation."
    },
    {
      "quote": "The court order or decree must be final:",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Any court order or decree submitted must be final."
    }
  ]
}

units.quote:
Court orders or decrees:

(a) Name change orders; or

(b) Divorce decrees;
